using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class BuildIndependentGoldenVFX{
const string Dest="Assets/3DBattle/Boss2/GoldenSlashVFX";
static void Folder(string p){if(AssetDatabase.IsValidFolder(p))return;Folder(Path.GetDirectoryName(p).Replace('\\','/'));AssetDatabase.CreateFolder(Path.GetDirectoryName(p).Replace('\\','/'),Path.GetFileName(p));}
static Dictionary<string,string> map=new Dictionary<string,string>();
static UnityEngine.Object Remap(UnityEngine.Object obj){if(obj==null)return null;string path=AssetDatabase.GetAssetPath(obj);if(!map.ContainsKey(path))return obj;string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(obj,out guid,out id);return AssetDatabase.LoadAllAssetsAtPath(map[path]).FirstOrDefault(o=>{string g;long n;return AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out g,out n)&&n==id;})??AssetDatabase.LoadAllAssetsAtPath(map[path]).First(o=>o.GetType()==obj.GetType()&&o.name==obj.name);}
static void Fix(UnityEngine.Object o){var so=new SerializedObject(o);var p=so.GetIterator();bool change=false;while(p.Next(true))if(p.propertyType==SerializedPropertyType.ObjectReference&&p.objectReferenceValue!=null){var replacement=Remap(p.objectReferenceValue);if(replacement!=p.objectReferenceValue){p.objectReferenceValue=replacement;change=true;}}if(change){so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(o);}}
public static string Run(){if(Application.isPlaying)throw new Exception("Edit mode required");Folder(Dest);string output=Dest+"/B2GoldenSlash.prefab";if(AssetDatabase.LoadAssetAtPath<GameObject>(output)!=null)throw new Exception("Already built");
var root=new GameObject("B2 Golden Slash");var visual=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Free Slash VFX/Prefabs/Projectiles/Slash Projectile VFX Fire.prefab"));PrefabUtility.UnpackPrefabInstance(visual,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);visual.name="Golden Crescent and Trails";visual.transform.SetParent(root.transform,false);
try{var decal=visual.transform.Find("Decal");if(decal!=null)UnityEngine.Object.DestroyImmediate(decal.gameObject);foreach(var b in visual.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(b);
 foreach(var p in visual.GetComponentsInChildren<ParticleSystem>(true)){p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=p.main;m.playOnAwake=true;m.loop=true;m.scalingMode=ParticleSystemScalingMode.Hierarchy;var c=m.startColor;Color tint=new Color(1,.85f,.35f,1);if(c.mode==ParticleSystemGradientMode.Color){var old=c.color;m.startColor=new Color(tint.r,tint.g,tint.b,old.a);}var collision=p.collision;collision.enabled=false;}
 var core=visual.GetComponent<ParticleSystem>();var mesh=visual.GetComponent<ParticleSystemRenderer>().mesh;float size=core.main.startSize.constantMax;float width=mesh.bounds.size.x*size;
 visual.transform.localRotation=Quaternion.Euler(0,0,90);visual.transform.localScale=Vector3.one/width;visual.transform.localPosition=-(visual.transform.localRotation*(mesh.bounds.center*size))/width;
 PrefabUtility.SaveAsPrefabAsset(root,output);
 var dependencies=AssetDatabase.GetDependencies(output,true).Where(p=>p.StartsWith("Assets/Free Slash VFX/")&&!AssetDatabase.IsValidFolder(p)).ToArray();
 foreach(var p in dependencies){string target=Dest+"/Source/"+p.Substring("Assets/Free Slash VFX/".Length);Folder(Path.GetDirectoryName(target).Replace('\\','/'));if(!AssetDatabase.CopyAsset(p,target))throw new Exception("Copy failed "+p);map[p]=target;}
 // Shader Graph files are JSON: redirect their internal texture/subgraph GUIDs too.
 foreach(var target in map.Values.Where(p=>p.EndsWith(".shadergraph")||p.EndsWith(".shadersubgraph"))){string text=File.ReadAllText(target);foreach(var pair in map)text=text.Replace(AssetDatabase.AssetPathToGUID(pair.Key),AssetDatabase.AssetPathToGUID(pair.Value));File.WriteAllText(target,text);AssetDatabase.ImportAsset(target,ImportAssetOptions.ForceSynchronousImport);}
 foreach(var p in map.Values.Where(p=>p.EndsWith(".mat"))){var m=AssetDatabase.LoadAssetAtPath<Material>(p);Fix(m);foreach(var prop in Enumerable.Range(0,m.shader.GetPropertyCount()).Where(i=>m.shader.GetPropertyType(i)==UnityEngine.Rendering.ShaderPropertyType.Color).Select(i=>m.shader.GetPropertyName(i))){var old=m.GetColor(prop);if(old.a==0)continue;float brightness=Mathf.Max(old.r,old.g,old.b);Color gold=prop.Contains("Back")?new Color(1,.6f,.08f,old.a):new Color(1,.86f,.36f,old.a);m.SetColor(prop,new Color(gold.r*brightness,gold.g*brightness,gold.b*brightness,old.a));}EditorUtility.SetDirty(m);}
 foreach(var c in root.GetComponentsInChildren<Component>(true))Fix(c);PrefabUtility.SaveAsPrefabAsset(root,output);AssetDatabase.SaveAssets();
 var remaining=AssetDatabase.GetDependencies(output,true).Where(p=>p.StartsWith("Assets/Free Slash VFX/")).ToArray();if(remaining.Length>0)throw new Exception("External references: "+string.Join(",",remaining));
 return "Independent prefab created; copied assets="+map.Count+"; original core mesh bounds="+mesh.bounds+" startSize="+size+" normalized scale="+visual.transform.localScale+"; no Free Slash VFX references.";
}finally{UnityEngine.Object.DestroyImmediate(root);}
}}
